-- GEANT / Sales AI: 100-row demonstration product catalog
-- Target: PostgreSQL schema after running `alembic upgrade head`.
-- Prices, stock quantities and specifications are illustrative demo data, not live retailer data.
-- Safe to re-run: existing rows with the same product name are not duplicated.
BEGIN;
CREATE TEMP TABLE _geant_seed_products (
  name VARCHAR(255) PRIMARY KEY, category VARCHAR(100) NOT NULL, brand VARCHAR(100),
  description TEXT, price NUMERIC(12,2), in_stock BOOLEAN, stock_quantity INTEGER, specs JSONB NOT NULL
) ON COMMIT DROP;

-- Insert products without replacing or deleting existing records.
SELECT s.name, s.category, s.brand, s.description, s.price, 'DZD', s.in_stock, NULL, TRUE, s.stock_quantity, NULL
FROM _geant_seed_products s
WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.name = s.name);

-- Insert/update specifications for the 100 catalog entries.
SELECT p.id, entry.key, spec.value_text, spec.value_num, spec.unit
FROM _geant_seed_products s
JOIN products p ON p.name = s.name
CROSS JOIN LATERAL jsonb_each(s.specs) AS entry(key, value)
CROSS JOIN LATERAL jsonb_to_record(entry.value) AS spec(value_text TEXT, value_num NUMERIC, unit TEXT)
ON CONFLICT (product_id, key) DO UPDATE SET
  value_text = EXCLUDED.value_text, value_num = EXCLUDED.value_num, unit = EXCLUDED.unit;

COMMIT;

-- Verify the imported catalog:
SELECT COUNT(*) AS imported_demo_products FROM products WHERE is_test_data = TRUE;
SELECT category, COUNT(*) AS product_count FROM products WHERE is_test_data = TRUE GROUP BY category ORDER BY category;